def sub(p):return (p['name'].lower() if p.get('inline') else '{'+p['name'].lower()+'}')+'_{'+str(p['i'])+str(p['j'])+'}'
def matrix(p,inline=False,name=None,period=False):
    rows=r' \\ '.join(' & '.join(row) for row in p['matrix'])
